#!/bin/bash
# Proxmox Host Monitor installer, generated by Home Assistant.
#
#   --check   only list existing installations and similar services, change nothing
#   --yes     replace existing installations without asking
set -euo pipefail

VERSION="@VERSION@"
WEBHOOK_URL=@WEBHOOK_URL@

MODE=install
case "${1:-}" in
    --check) MODE=check ;;
    --yes) MODE=yes ;;
    "") ;;
    *) echo "Unknown option: $1" >&2; exit 2 ;;
esac

if [ "$(id -u)" != 0 ]; then
    echo "Please run as root." >&2
    exit 1
fi

OWN_UNITS="proxmox-host-monitor-reboot proxmox-host-monitor-disks"
LEGACY_FILES="/etc/systemd/system/proxmox-reboot-status.timer /etc/systemd/system/proxmox-reboot-status.service /usr/local/sbin/report-reboot-status-to-ha"

# Print "kind<TAB>description<TAB>path" for everything that already exists.
# kind: own (updated), legacy (removed), foreign (timer disabled), info (only listed)
detect() {
    if [ -e /usr/local/sbin/proxmox-host-monitor-reboot ]; then
        local installed
        installed=$(cat /etc/proxmox-host-monitor/version 2>/dev/null || echo unknown)
        printf 'own\tProxmox Host Monitor %s (update to %s)\t/usr/local/sbin/proxmox-host-monitor-*\n' "$installed" "$VERSION"
    fi
    for file in $LEGACY_FILES; do
        [ -e "$file" ] && printf 'legacy\tProxmox Reboot Update\t%s\n' "$file"
    done

    local unit exec_path
    for unit in /etc/systemd/system/*.service; do
        [ -e "$unit" ] || continue
        case "$(basename "$unit" .service)" in
            proxmox-host-monitor-*|proxmox-reboot-status) continue ;;
        esac
        exec_path=$(sed -n 's/^ExecStart=[-@+!]*\([^ ]*\).*/\1/p' "$unit" | head -n 1)
        if grep -qsIE '/api/webhook/|smartctl' "$unit" ${exec_path:+"$exec_path"}; then
            printf 'foreign\tService reporting to Home Assistant or reading SMART: %s\t%s\n' \
                "$(basename "$unit")" "${exec_path:-$unit}"
        fi
    done

    for hook in /etc/smartmontools/run.d/*; do
        [ -e "$hook" ] || continue
        case "$(basename "$hook")" in
            60proxmox-host-monitor|10mail) continue ;;
        esac
        printf 'foreign\tsmartd hook\t%s\n' "$hook"
    done

    for cron in /etc/cron.d/* /var/spool/cron/crontabs/root; do
        [ -e "$cron" ] || continue
        if grep -qs '/api/webhook/' "$cron"; then
            printf 'info\tCron job reporting to Home Assistant (left unchanged)\t%s\n' "$cron"
        fi
    done
    return 0
}

FOUND=$(detect)

if [ "$MODE" = check ]; then
    [ -n "$FOUND" ] && printf '%s\n' "$FOUND"
    exit 0
fi

if [ -n "$FOUND" ] && [ "$MODE" != yes ]; then
    echo "Found existing installations or similar services:"
    printf '%s\n' "$FOUND" | while IFS=$'\t' read -r kind description path; do
        case "$kind" in
            own) action="update" ;;
            legacy) action="remove" ;;
            foreign) action="disable" ;;
            *) action="keep" ;;
        esac
        printf '  [%s] %s\n        %s\n' "$action" "$description" "$path"
    done
    if ! { exec 3</dev/tty; } 2>/dev/null; then
        echo "No terminal to ask. Re-run with --yes to replace them." >&2
        exit 3
    fi
    read -r -u 3 -p "Overwrite/update? [y/N] " answer
    case "$answer" in
        y|Y|yes|j|J|ja) ;;
        *) echo "Aborted, nothing changed."; exit 3 ;;
    esac
fi

command -v pveversion >/dev/null || echo "Warning: this does not look like a Proxmox VE host." >&2

if ! command -v smartctl >/dev/null; then
    DEBIAN_FRONTEND=noninteractive apt-get install -y smartmontools
fi

# Replace what was found.
printf '%s\n' "$FOUND" | while IFS=$'\t' read -r kind description path; do
    case "$kind" in
        legacy)
            case "$path" in
                *.timer|*.service) systemctl disable --now "$(basename "$path")" 2>/dev/null || true ;;
            esac
            rm -f "$path"
            echo "Removed $path"
            ;;
        foreign)
            if [ -d /etc/smartmontools/run.d ] && [ "$(dirname "$path")" = /etc/smartmontools/run.d ]; then
                chmod -x "$path"
                echo "Disabled smartd hook $path"
            else
                for unit in /etc/systemd/system/*.service; do
                    grep -qsF "$path" "$unit" || [ "$unit" = "$path" ] || continue
                    name=$(basename "$unit" .service)
                    systemctl disable --now "$name.timer" 2>/dev/null || true
                    echo "Disabled $name (files kept)"
                done
            fi
            ;;
    esac
done

mkdir -p /etc/proxmox-host-monitor
printf '%s\n' "$WEBHOOK_URL" > /etc/proxmox-host-monitor/webhook-url
printf '%s\n' "$VERSION" > /etc/proxmox-host-monitor/version
chmod 600 /etc/proxmox-host-monitor/webhook-url

cat > /usr/local/sbin/proxmox-host-monitor-reboot <<'PHM_EOF'
@REBOOT_SCRIPT@PHM_EOF
cat > /usr/local/sbin/proxmox-host-monitor-disks <<'PHM_EOF'
@DISK_SCRIPT@PHM_EOF
chmod 750 /usr/local/sbin/proxmox-host-monitor-reboot /usr/local/sbin/proxmox-host-monitor-disks

cat > /etc/systemd/system/proxmox-host-monitor-reboot.service <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report reboot status to Home Assistant
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/proxmox-host-monitor-reboot
PHM_EOF

cat > /etc/systemd/system/proxmox-host-monitor-reboot.timer <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report reboot status every 5 minutes

[Timer]
OnBootSec=2min
OnUnitActiveSec=5min
Persistent=true

[Install]
WantedBy=timers.target
PHM_EOF

cat > /etc/systemd/system/proxmox-host-monitor-disks.service <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report disk health to Home Assistant
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/proxmox-host-monitor-disks
Nice=10
PHM_EOF

cat > /etc/systemd/system/proxmox-host-monitor-disks.timer <<'PHM_EOF'
[Unit]
Description=Proxmox Host Monitor: report disk health every 15 minutes

[Timer]
OnBootSec=3min
OnUnitActiveSec=15min
Persistent=true

[Install]
WantedBy=timers.target
PHM_EOF

mkdir -p /etc/smartmontools/run.d
cat > /etc/smartmontools/run.d/60proxmox-host-monitor <<'PHM_EOF'
#!/bin/sh
# Report smartd warnings to Home Assistant immediately.
systemctl start --no-block proxmox-host-monitor-disks.service
PHM_EOF
chmod 755 /etc/smartmontools/run.d/60proxmox-host-monitor

systemctl daemon-reload
for unit in $OWN_UNITS; do
    systemctl enable --now "$unit.timer"
    systemctl start "$unit.service"
done
echo "Proxmox Host Monitor $VERSION installed."
